INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann ein Hardwareproblem im Anwendersupport durch einen defekten Monitor verursacht werden?', 2, '[{"text": "Ja", "correct": true, "because": "Monitor ist Hardware"}, {"text": "Nein", "correct": false, "because": "Monitore können ausfallen"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss bei einem Hardwareproblem immer ein Techniker vor Ort sein?', 2, '[{"text": "Nein", "correct": true, "because": "Diagnose oft remote möglich"}, {"text": "Ja", "correct": false, "because": "Nicht immer erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Überhitzen der CPU ein technisches Hardwareproblem?', 2, '[{"text": "Ja", "correct": true, "because": "Überhitzen ist Hardwarefehler"}, {"text": "Nein", "correct": false, "because": "CPU ist Hardware"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Hardwareproblem durch lose Kabelverbindungen entstehen?', 2, '[{"text": "Ja", "correct": true, "because": "Lose Verbindungen sind häufig"}, {"text": "Nein", "correct": false, "because": "Kabelprobleme sind Hardware"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Hardwareprobleme im Anwendersupport immer sofort erkennbar?', 2, '[{"text": "Nein", "correct": true, "because": "Diagnose kann nötig sein"}, {"text": "Ja", "correct": false, "because": "Nicht immer offensichtlich"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Hardwareproblem führt dazu, dass ein Computer nicht startet?', 2, '[{"text": "Defektes Netzteil", "correct": true, "because": "Keine Stromversorgung"}, {"text": "Fehlende Maus", "correct": false, "because": "Start nicht verhindert"}, {"text": "Langsamer Prozessor", "correct": false, "because": "Beeinflusst Leistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Symptom weist auf ein Hardwareproblem mit der Festplatte hin?', 3, '[{"text": "Klickgeräusche", "correct": true, "because": "Mechanischer Defekt"}, {"text": "Langsames Internet", "correct": false, "because": "Netzwerkproblem"}, {"text": "Bildschirmflackern", "correct": false, "because": "Monitorproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist der erste Schritt bei einem vermuteten Hardwareproblem im Anwendersupport?', 2, '[{"text": "Sichtprüfung", "correct": true, "because": "Überprüft physische Schäden"}, {"text": "Software-Update", "correct": false, "because": "Softwarebezogen"}, {"text": "Neustart", "correct": false, "because": "Allgemeiner Schritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hardwarekomponente ist oft für Überhitzungsprobleme verantwortlich?', 2, '[{"text": "Lüfter", "correct": true, "because": "Kühlung versagt"}, {"text": "Tastatur", "correct": false, "because": "Keine Kühlfunktion"}, {"text": "Monitor", "correct": false, "because": "Unabhängig von Hitze"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft bei der Diagnose eines Hardwareproblems?', 2, '[{"text": "Multimeter", "correct": true, "because": "Misst Stromfluss"}, {"text": "Texteditor", "correct": false, "because": "Softwaretool"}, {"text": "Browser", "correct": false, "because": "Kein Diagnosetool"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Hardwarekomponenten können im Anwendersupport Probleme verursachen?', 3, '[{"text": "Festplatte", "correct": true, "because": "Mechanische Fehler"}, {"text": "Grafikkarte", "correct": true, "because": "Bildprobleme"}, {"text": "Netzteil", "correct": true, "because": "Stromausfall"}, {"text": "Betriebssystem", "correct": false, "because": "Software"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Symptome deuten auf Hardwareprobleme im Anwendersupport hin?', 4, '[{"text": "Kein Einschalten", "correct": true, "because": "Netzteil defekt"}, {"text": "Ungewöhnliche Geräusche", "correct": true, "because": "Mechanische Fehler"}, {"text": "Bildschirmflackern", "correct": true, "because": "Grafikkarte/Monitor"}, {"text": "Langsame Programme", "correct": false, "because": "Softwareproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen helfen bei Hardwareproblemen im Anwendersupport?', 3, '[{"text": "Kabel überprüfen", "correct": true, "because": "Lose Ver bindungen"}, {"text": "Komponenten austauschen", "correct": true, "because": "Defekte Teile"}, {"text": "Reinigung von Staub", "correct": true, "because": "Verhindert Überhitzen"}, {"text": "Software neu installieren", "correct": false, "because": "Softwarelösung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hardwarefehler können im Anwendersupport auftreten?', 4, '[{"text": "Überhitzung", "correct": true, "because": "Lüfterausfall"}, {"text": "Kurzschluss", "correct": true, "because": "Stromproblem"}, {"text": "Mechanischer Defekt", "correct": true, "because": "Festplatte"}, {"text": "Falsche IP-Adresse", "correct": false, "because": "Netzwerkproblem"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Diagnosemethoden werden bei Hardwareproblemen im Anwendersupport genutzt?', 3, '[{"text": "Sichtprüfung", "correct": true, "because": "Physische Schäden"}, {"text": "POST-Test", "correct": true, "because": "Startdiagnose"}, {"text": "Temperaturmessung", "correct": true, "because": "Überhitzung prüfen"}, {"text": "Antivirus-Scan", "correct": false, "because": "Softwarelösung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein defekter Lüfter kann ein Hardwareproblem sein. b) Hardwareprobleme betreffen nie die Stromversorgung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lüfter ja, Stromversorgung auch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein schwarzer Bildschirm kann ein Hardwareproblem sein. b) Hardwareprobleme lassen sich immer remote lösen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bildschirm ja, remote nicht immer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Klickgeräusche deuten auf ein Festplattenproblem hin. b) Ein Hardwareproblem ist nie durch Staub verursacht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Festplatte ja, Staub kann Ursache sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Eine Sichtprüfung hilft bei Hardwareproblemen. b) Ein defektes Netzteil verursacht keine Probleme beim Starten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Sichtprüfung ja, Netzteil relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Hardwareprobleme können durch Überhitzung entstehen. b) Eine kaputte Maus verhindert das Einschalten des PCs.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Überhitzung ja, Maus nicht kritisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

